// access token issued at login, no refresh token in use
const token = jwt.sign(
  { sub: user.id, roles: user.roles },
  process.env.JWT_SECRET,
  { expiresIn: '7d' }            // 7-day access token
);
// client stores it:
localStorage.setItem('access_token', token);

// logout endpoint
app.post('/logout', (req, res) => {
  // tell the browser to forget the token
  res.clearCookie('hint');
  return res.json({ ok: true }); // 'logged out'
});

// auth middleware on every protected route
function auth(req, res, next) {
  const t = req.headers.authorization?.replace('Bearer ', '');
  req.user = jwt.verify(t, process.env.JWT_SECRET); // valid signature + not expired => allowed
  next();
}
